#!/usr/bin/env python3
"""Source-pinned generation-free model identity audit."""
import base64,gzip,hashlib,sys,types
sys.dont_write_bytecode=True
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='cb22df37c3b716c44c7fb8ab1828e4b220706ae985583bcfdb5ea58d4d596e65':raise RuntimeError("HOLD_IDENTITY_MODULE_SHA")
m=types.ModuleType('model_identity_projection');m.__file__='<reviewed-model_identity_projection>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='e2c6fe0db7712bbecb1d12ab135cef76043eb37fa3797f192dfa56d40404fde7':raise RuntimeError("HOLD_IDENTITY_MODULE_SHA")
m=types.ModuleType('native_model_identity_readback');m.__file__='<reviewed-native_model_identity_readback>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='5cca3c2d88c5072bfa079f17ed4d936a452b1155486427bc3e8982466e1dced0':raise RuntimeError("HOLD_IDENTITY_MODULE_SHA")
m=types.ModuleType('model_identity_audit_entry');m.__file__='<reviewed-model_identity_audit_entry>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raise SystemExit(m.main())
